        return check_packet_ptr_alignment(env, reg, off, size);
    else if (reg->type == PTR_TO_CTX)
        return check_ctx_ptr_alignment(env, reg, off, size);
    else if (reg->type == PTR_TO_STACK)
        return check_stack_ptr_alignment(env, reg, off, size);
    else
        return 0; // Assume aligned for other pointer types by default
