int check_ptr_alignment(struct bpf_verifier_env *env, const struct bpf_reg_state *reg, int off, int size) {
    int ptr_type = reg->type;
    int align = 0;

    switch (ptr_type) {
        case PTR_TO_PACKET:
        case PTR_TO_PACKET_META:
        case PTR_TO_PACKET_END:
            align = 1;
            break;
        case PTR_TO_CTX:
            align = 4;
            break;
        case PTR_TO_MAP_KEY:
        case PTR_TO_MAP_VALUE:
            align = 8;
            break;
        default:
            // For unknown or other pointer types, assume 1-byte alignment
            align = 1;
            break;
    }

    int total_offset = off + reg->off;
    if (total_offset % align != 0) {
        return -EINVAL;
    }

    return 0;
}

int check_ptr_alignment(struct bpf_verifier_env *env, const struct bpf_reg_state *reg, int off, int size) {
    int err;

    switch (reg->type) {
    case PTR_TO_PACKET:
    case PTR_TO_PACKET_META:
        err = check_packet_ptr_alignment(env, reg, off, size);
        break;
    case PTR_TO_CTX:
        err = check_ctx_ptr_alignment(env, reg, off, size);
        break;
    default:
        /* Default alignment check for other pointer types */
        if ((reg->off + off) % size != 0) {
            verbose(env, "Pointer is not aligned to %d bytes\n", size);
            return -EINVAL;
        }
        err = 0;
        break;
    }

    return err;
}
